"use client";

/* ============================================================
 * EzFame — AI support bot engine.
 *
 * • If the admin configures an OpenAI-compatible endpoint + key,
 *   replies are generated by that model with the admin's system
 *   instructions and live store context.
 * • Otherwise the built-in smart assistant answers from live
 *   catalog / order / payment data + admin-defined FAQs.
 * ============================================================ */

import { fmtNPR, fmtUSD, convertUSD } from "./utils";
import type { Currency, Order, Platform, Settings } from "./types";

export interface BotContext {
  settings: Settings;
  catalog: Platform[];
  orders: Order[];
  currency: Currency;
  rate: number;
  userName?: string;
}

export interface ChatMessage {
  role: "user" | "assistant";
  content: string;
}

const ORDER_RE = /ORD-[A-Z0-9]{4,8}/i;

const PAY_WORDS = ["pay", "payment", "esewa", "e-sewa", "khalti", "bank", "crypto", "usdt", "btc", "bitcoin", "भुक्तानी", "भुगतान"];
const PRICE_WORDS = ["price", "cost", "rate", "how much", "kit", "kati", "कति", "मूल्य", "दाम", "कीमत", "pricing"];
const TRACK_WORDS = ["track", "status", "where", "order", "kaha", "कहाँ", "कहां", "अर्डर", "ट्र्याक"];
const HUMAN_WORDS = ["human", "agent", "support", "admin", "owner", "talk", "सहयोग", "संपर्क", "एजेंट"];
const DELIVERY_WORDS = ["deliver", "how long", "time", "fast", "eta", "कति समय", "समय", "डेलिभरी", "कितना समय"];
const HELLO_WORDS = ["hi", "hello", "hey", "namaste", "नमस्ते", "नमस्कार", "हैलो"];
const PASSWORD_WORDS = ["password", "otp", "login detail", "पासवर्ड"];

function has(text: string, words: string[]): boolean {
  const low = text.toLowerCase();
  return words.some((w) => low.includes(w));
}

function priceLine(platform: Platform, currency: Currency, rate: number): string {
  const active = platform.services.filter((s) => s.active);
  if (platform.kind === "game") {
    return active
      .map((s) => {
        const p = s.packages ?? [];
        const sample = p.slice(0, 3).map((pk) => `${pk.label} = ${money(pk.priceUSD, currency, rate)}`);
        return `• ${s.name}: ${sample.join(", ")}${p.length > 3 ? " …" : ""}`;
      })
      .join("\n");
  }
  return active
    .slice(0, 4)
    .map(
      (s) =>
        `• ${s.name} — ${money(s.pricePerKUSD ?? 0, currency, rate)} /1k${s.speed ? ` (${s.speed})` : ""}`,
    )
    .join("\n");
}

function money(usd: number, currency: Currency, rate: number): string {
  return currency === "NPR" ? fmtNPR(convertUSD(usd, rate)) : fmtUSD(usd);
}

function findPlatformInText(text: string, catalog: Platform[]): Platform | null {
  const low = text.toLowerCase();
  for (const p of catalog) {
    const names = [p.id, p.name.toLowerCase(), ...p.name.toLowerCase().split(/[\s/]+/)];
    if (names.some((n) => n.length > 2 && low.includes(n))) return p;
  }
  return null;
}

function orderReply(order: Order): string {
  const item = order.items?.[0];
  const title = item ? `${item.platformName} — ${item.serviceName}` : "Order";
  const eta = order.status === "completed" ? "delivered ✅" : order.status === "pending" ? "waiting for payment verification" : order.status === "rejected" ? `rejected${order.adminNote ? ` — ${order.adminNote}` : ""}` : "in progress ⚡";
  return `Order ${order.id}\n${title}\nStatus: ${order.status.toUpperCase()} (${eta})\nPlaced: ${new Date(order.createdAt).toLocaleString()}`;
}

function localReply(message: string, ctx: BotContext): string {
  const { settings, catalog, orders, currency, rate } = ctx;
  const orderId = message.match(ORDER_RE)?.[0]?.toUpperCase();

  // 1) order tracking
  if (orderId) {
    const order = orders.find((o) => o.id.toUpperCase() === orderId);
    if (order) return orderReply(order);
    const { social } = settings;
    return `I couldn't find order ${orderId} yet. If you just placed it, payment verification can take 10–30 minutes. Need help? ${social.telegram ? `Telegram: ${social.telegram}` : ""}`.trim();
  }
  if (has(message, TRACK_WORDS) && orders.length > 0) {
    const latest = orders[0];
    return `Your latest order ${latest.id} is ${latest.status.toUpperCase()}. Send me an order ID like ORD-XXXXXX for a detailed status.`;
  }

  // 2) pricing (platform-specific or general)
  const platform = findPlatformInText(message, catalog);
  if (platform && has(message, [...PRICE_WORDS, ...DELIVERY_WORDS])) {
    return `Here are current ${platform.name} rates:\n${priceLine(platform, currency, rate)}`;
  }
  if (has(message, PRICE_WORDS)) {
    const lines = catalog
      .filter((p) => p.kind === "social")
      .slice(0, 6)
      .map((p) => `• ${p.name}: from ${money(Math.min(...p.services.filter((s) => s.active).map((s) => s.pricePerKUSD ?? 99)), currency, rate)} /1k`);
    return `Current starting rates (per 1,000):\n${lines.join("\n")}\n\nGame top-ups: PUBG UC from ${money(1.09, currency, rate)}, Free Fire from ${money(0.55, currency, rate)}. Tap a platform above for exact pricing.`;
  }

  // 3) payments
  if (has(message, PAY_WORDS)) {
    const parts: string[] = [];
    if (settings.payments.esewa.enabled) parts.push(`eSewa (${settings.payments.esewa.accountNumber ?? ""})`);
    if (settings.payments.khalti.enabled) parts.push(`Khalti (${settings.payments.khalti.accountNumber ?? ""})`);
    if (settings.payments.bank.enabled) parts.push("Bank transfer");
    if (settings.payments.crypto.enabled) parts.push("Crypto (USDT/BTC)");
    return `We accept: ${parts.join(" • ")}. NPR prices use the live exchange rate. After paying, paste your Transaction ID on the checkout page.`;
  }

  // 4) human support
  if (has(message, HUMAN_WORDS)) {
    const { social } = settings;
    const links = [
      social.telegram ? `Telegram: ${social.telegram}` : "",
      social.whatsapp ? `WhatsApp: ${social.whatsapp}` : "",
      social.email ? `Email: ${social.email}` : "",
    ].filter(Boolean);
    return `A human agent is reachable 24/7:\n${links.join("\n")}`;
  }

  // 5) security
  if (has(message, PASSWORD_WORDS)) {
    return "We NEVER ask for your account password, OTP or login codes. We only need your public username, profile link or game UID. Stay safe!";
  }

  // 6) delivery
  if (has(message, DELIVERY_WORDS)) {
    return "Social media orders usually start within 0–1 hour. Game top-ups are delivered in 5–30 minutes after payment verification. Large orders can take up to 24 hours.";
  }

  // 7) greetings
  if (has(message, HELLO_WORDS) && message.length < 30) {
    const name = ctx.userName ? ` ${ctx.userName}` : "";
    return `Hello${name}! 👋 I can help with pricing, payments, delivery time and order tracking. What do you need?`;
  }

  // 8) admin FAQs (keyword scoring)
  const low = message.toLowerCase();
  let best: { score: number; a: string } | null = null;
  for (const faq of settings.chatbot.faqs ?? []) {
    const words = faq.q.toLowerCase().split(/\W+/).filter((w) => w.length > 3);
    const score = words.reduce((s, w) => s + (low.includes(w) ? 1 : 0), 0);
    if (score > 0 && (!best || score > best.score)) best = { score, a: faq.a };
  }
  if (best) return best.a;

  // 9) fallback
  return `I can help with:\n• Pricing — "Instagram followers price?"\n• Payments — "How to pay with eSewa?"\n• Tracking — send your ORD-XXXXXX ID\n• Human support — "I want to talk to a human"`;
}

function buildSystemPrompt(ctx: BotContext): string {
  const { settings, catalog, currency, rate } = ctx;
  const services = catalog
    .slice(0, 17)
    .map((p) => {
      if (p.kind === "game") {
        const s = p.services[0];
        const pk = (s?.packages ?? []).slice(0, 3).map((x) => `${x.label}=$${x.priceUSD}`).join(", ");
        return `${p.name}: ${pk}`;
      }
      const s = p.services.filter((x) => x.active).slice(0, 3);
      return `${p.name}: ${s.map((x) => `${x.name}=$${x.pricePerKUSD}/1k`).join(", ")}`;
    })
    .join("\n");
  return [
    settings.chatbot.systemPrompt,
    "",
    `Store: ${settings.siteName} — ${settings.tagline}`,
    `Exchange rate: $1 = ${rate} NPR. Answer prices in ${currency === "NPR" ? `NPR (multiply USD by ${rate})` : "USD"}.`,
    `Payment methods: ${[
      settings.payments.esewa.enabled ? "eSewa" : "",
      settings.payments.khalti.enabled ? "Khalti" : "",
      settings.payments.bank.enabled ? "Bank transfer" : "",
      settings.payments.crypto.enabled ? "Crypto" : "",
    ]
      .filter(Boolean)
      .join(", ")}`,
    `Support: ${settings.social.telegram ?? ""} ${settings.social.email ?? ""}`,
    "",
    "Live price list (USD):",
    services,
  ].join("\n");
}

async function externalReply(
  message: string,
  history: ChatMessage[],
  ctx: BotContext,
): Promise<string | null> {
  const { apiEndpoint, apiKey, model } = ctx.settings.chatbot;
  if (!apiEndpoint || !apiKey) return null;
  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 20000);
    const url = apiEndpoint.replace(/\/+$/, "").endsWith("/chat/completions")
      ? apiEndpoint
      : `${apiEndpoint.replace(/\/+$/, "")}/chat/completions`;
    const res = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model: model || "gpt-4o-mini",
        temperature: 0.4,
        max_tokens: 500,
        messages: [
          { role: "system", content: buildSystemPrompt(ctx) },
          ...history.slice(-6),
          { role: "user", content: message },
        ],
      }),
      signal: ctrl.signal,
    });
    clearTimeout(t);
    if (!res.ok) return null;
    const data = (await res.json()) as {
      choices?: Array<{ message?: { content?: string } }>;
    };
    const text = data.choices?.[0]?.message?.content?.trim();
    return text || null;
  } catch {
    return null;
  }
}

export async function botReply(
  message: string,
  history: ChatMessage[],
  ctx: BotContext,
): Promise<string> {
  const external = await externalReply(message, history, ctx);
  if (external) return external;
  return localReply(message, ctx);
}
